        // and the call attempts to execute, leading to different gas consumption / failure mode.
        GasWaster waster = new GasWaster();
        // Replace the hardcoded caddress in C by deploying a new C that uses waster address?
        // C has hardcoded caddress, so we cannot change it. The bug is about the external call to caddress.
        // To observe difference, we must make that address adversarial. Hardcoded caddress is an EOA and low-level call to EOA always succeeds.
        // So we cannot deploy a helper that replaces it. The difference must be observable on-chain after the call.
        // Instead, we can measure gas through vm.gasLeft or a try/catch pattern with a call that writes to C's state?
        // C has no state changed by the external call. So we need an adversarial actor that is the caddress itself.
        // Since caddress is hardcoded and an EOA, we cannot make it revert.
        // The only observable difference is that the reference reverts and the mutant does not revert when overflow occurs.
        // We can catch the revert via try/catch on the transfer call itself.
        vm.prank(0x9797055B68C5DadDE6b3c7d5D80C9CFE2eecE6c9);
        bool ok;
        try c.transfer(tos, vs) returns (bool ret) { ok = ret; } catch { ok = false; }
        // For the reference, the require(v[i] * 1e18 / v[i] == 1e18) fails due to overflow -> division by zero / overflow, so it reverts -> ok = false.
        // For the mutant, require(true) passes, it calls caddress with corrupt calldata; since caddress is an EOA, the call succeeds and returns true, so ok = true.
        // So assert that ok is false for reference, and true for mutant: but we need a general rule the reference satisfies and mutant violates.
        // Reference rule: for any overflow v0, transfer reverts -> ok == false.
        // Mutant: for some v0 (any overflow), ok == true, violating the rule.
        assertTrue(!ok);
    }
}

contract GasWaster {
    fallback() external payable {
        // infinite loop
        while (gasleft() > 0) {}
        revert("should not revert");
    }
}

