        try c.transfer(_tos, v) returns (bool ret) {
            ok = true;
        } catch {
            ok = false;
        }
        uint256 unscaled;
        bool willOverflow = false;
        for (uint i = 0; i < v.length; i++) {
            unscaled = v[i] * 1000000000000000000;
            if (unscaled / 1000000000000000000 != v[i]) {
                willOverflow = true;
                break;
            }
        }
        if (willOverflow) {
            assertFalse(ok);
        }
    }
